import { describe, expect, it } from 'vitest';
import { sequentialIdFactory } from '../ir/ids';
import { emptyProgram, programFromCommands } from '../ir/program';
import { lineNodeIds, printProgram } from './printTs';

describe('printProgram', () => {
  it('prints an empty program', () => {
    expect(printProgram(emptyProgram())).toBe(
      [
        '// Generated by Wonderbits from program IR v1. Read-only.',
        "import { robot } from 'wonderbits';",
        '',
        'export function main(): void {',
        '  // No steps yet.',
        '}',
        '',
      ].join('\n'),
    );
  });

  it('prints one annotated statement per node', () => {
    const p = programFromCommands(['forward', 'rotateCW', 'rotateCCW'], sequentialIdFactory());
    expect(printProgram(p)).toMatchInlineSnapshot(`
      "// Generated by Wonderbits from program IR v1. Read-only.
      import { robot } from 'wonderbits';

      export function main(): void {
        robot.forward(); // @node n1
        robot.rotateClockwise(); // @node n2
        robot.rotateCounterClockwise(); // @node n3
      }
      "
    `);
  });

  it('is deterministic and lists every node id exactly once', () => {
    const p = programFromCommands(['forward', 'forward', 'rotateCW', 'forward'], sequentialIdFactory());
    const a = printProgram(p);
    expect(printProgram(structuredClone(p))).toBe(a);
    const ids = lineNodeIds(a).filter((x): x is string => x !== null);
    expect(ids).toEqual(['n1', 'n2', 'n3', 'n4']);
    expect(new Set(ids).size).toBe(ids.length);
  });
});
